// ---------- 1. Read input text ----------
const inputData = $input.item.json.content;

// ---------- 2. Helper: extract a block that starts with a bold header ----------
const grabBlock = (text, header) => {
  const re = new RegExp(`\\*{0,2}${header}\\*{0,2}\\s*([\\s\\S]*?)\\s*$`, 'i');
  const m = re.exec(text);
  return m ? m[1].trim() : null;
};

// ---------- 3. Helper: extract a section that sits between bold headers ----------
const grabSection = (text, label) => {
  /* takes "**Label:** ..." up to the next **Bold Header** or end */
  const re = new RegExp(
    `\\*{0,2}${label}\\*{0,2}\\s*([\\s\\S]*?)(?=\\n\\*{0,2}[A-Z][^\\n]*\\*{0,2}\\s*|$)`,
    'i'
  );
  const m = re.exec(text);
  return m ? m[1].trim() : null;
};

// ---------- 4. Pull the three simple sections ----------
const educationalQualifications = grabSection(inputData, 'Educational Qualifications:');
const jobHistory                = grabSection(inputData, 'Job History:');
const skillSet                  = grabSection(inputData, 'Skill Set:');

// ---------- 5. Pull the whole "Evaluation ..." block ----------
const evaluationBlock = grabBlock(inputData, 'Evaluation');

// ---------- 6. From that block, get score & justification ----------
let score = null;
let justification = null;

if (evaluationBlock) {
  // score can be "Relevance Score: 7/10" or "Score: 7/10"
  const scoreMatch = /(Relevance\s*)?Score:\**\s*(\d{1,2})\s*\/\s*10/i.exec(evaluationBlock);
  score = scoreMatch ? scoreMatch[2] : null;

  const justMatch = /\*{0,2}Justification:\*{0,2}\s*([\s\S]*)/i.exec(evaluationBlock);
  if (justMatch) {
    justification = justMatch[1].trim();
  }
}

// ---------- 7. Return tidy JSON ----------
// Mode is "Run Once for Each Item", so return ONE object (not an array).
return {
  educationalQualifications,
  jobHistory,
  skillSet,
  score,
  justification
};

// =============================================================
// BUILD EMAIL CONTENT
// Runs AFTER "Append row in sheet" (true branch of the score guard).
// Reads the parsed evaluation from the "Code" node and the
// contact details from the "Information Extractor" node.
// =============================================================

// ---------- 1. Pull data from the earlier nodes ----------
const evalData  = $('Code').item.json;
const extracted = $('Information Extractor').item.json.output || {};
const sender    = $('Gmail Trigger').item.json.from?.value?.[0] || {};

// ---------- 2. Decide who we are replying to ----------
// Prefer the address printed on the CV, fall back to the address
// the email was actually sent from.
const toEmail = extracted.email || sender.address;
const toName  = extracted.name || sender.name || 'Candidate';

if (!toEmail) {
  throw new Error('No recipient email address could be found.');
}

// ---------- 3. Normalise the score ----------
const parsed = Number(evalData.score);
const score  = Number.isFinite(parsed) ? parsed : 0;

// ---------- 4. Pick a verdict band ----------
let band, verdict;
if (score >= 9) {
  band = 'Excellent match';
  verdict = 'Your profile is a very strong fit for this role. Our team will ' +
            'contact you shortly to arrange an interview.';
} else if (score >= 7) {
  band = 'Strong match';
  verdict = 'Your profile aligns well with this role and has been shortlisted ' +
            'for further review.';
} else if (score >= 4) {
  band = 'Moderate match';
  verdict = 'Your profile matches several of our requirements. We will keep ' +
            'your CV on file for suitable openings.';
} else {
  band = 'Limited match';
  verdict = 'Your profile does not closely match this particular role, but we ' +
            'encourage you to apply for future openings.';
}

// ---------- 5. Helpers that keep the HTML safe ----------
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const nl2br = (v) => esc(v).replace(/\n/g, '<br>');

// ---------- 6. Build the subject line ----------
const subject = `Your Application Review - Score ${score}/10 (${band})`;

// ---------- 7. Build the HTML body ----------
const htmlBody = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:620px;
            margin:0 auto;color:#1f2933;line-height:1.6;">

  <h2 style="margin:0 0 4px;color:#0b3d91;">Application Review Summary</h2>
  <p style="margin:0 0 20px;color:#6b7280;font-size:13px;">
    Automated screening report - Junior AI Automation Engineer
  </p>

  <p>Hi ${esc(toName)},</p>

  <p>Thank you for sending us your CV. Our screening system has finished
     reviewing it. Here is a summary of the result.</p>

  <div style="background:#f3f6fb;border-left:5px solid #0b3d91;
              padding:14px 18px;margin:22px 0;">
    <div style="font-size:30px;font-weight:bold;color:#0b3d91;">
      ${score}<span style="font-size:16px;color:#6b7280;">/10</span>
    </div>
    <div style="font-size:14px;font-weight:bold;">${esc(band)}</div>
  </div>

  <p>${esc(verdict)}</p>

  <h3 style="margin:24px 0 6px;font-size:15px;color:#0b3d91;">
    Why you received this score
  </h3>
  <p style="margin:0;">${nl2br(evalData.justification)}</p>

  <h3 style="margin:24px 0 6px;font-size:15px;color:#0b3d91;">
    What we read from your CV
  </h3>
  <table style="width:100%;border-collapse:collapse;font-size:14px;">
    <tr>
      <td style="padding:8px;border:1px solid #dde3ec;width:32%;
                  background:#f9fafc;font-weight:bold;">Qualifications</td>
      <td style="padding:8px;border:1px solid #dde3ec;">
         ${nl2br(evalData.educationalQualifications)}</td>
    </tr>
    <tr>
      <td style="padding:8px;border:1px solid #dde3ec;
                  background:#f9fafc;font-weight:bold;">Job History</td>
      <td style="padding:8px;border:1px solid #dde3ec;">
         ${nl2br(evalData.jobHistory)}</td>
    </tr>
    <tr>
      <td style="padding:8px;border:1px solid #dde3ec;
                  background:#f9fafc;font-weight:bold;">Skill Set</td>
      <td style="padding:8px;border:1px solid #dde3ec;">
         ${nl2br(evalData.skillSet)}</td>
    </tr>
  </table>

  <p style="margin-top:24px;">Best regards,<br>
     <strong>The Recruitment Team</strong></p>

  <hr style="border:none;border-top:1px solid #e3e8ef;margin:26px 0 10px;">
  <p style="font-size:11px;color:#9aa5b1;margin:0;">
    This message was generated automatically. If any detail above looks wrong,
    simply reply to this email and a human will review it.
  </p>
</div>
`;

// ---------- 8. Hand everything to the Gmail node ----------
// Mode is "Run Once for Each Item", so return ONE object.
return { toEmail, toName, subject, htmlBody, score, band };

// =============================================================
// BUILD THANK-YOU EMAIL (false branch: score below 4)
// Short, polite note - no detailed report.
// =============================================================
const extracted = $('Information Extractor').item.json.output || {};
const sender    = $('Gmail Trigger').item.json.from?.value?.[0] || {};
const toEmail = extracted.email || sender.address;
const toName  = extracted.name || sender.name || 'Candidate';
if (!toEmail) throw new Error('No recipient email address could be found.');

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const subject = 'Thank you for your application';
const htmlBody = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:620px;margin:0 auto;color:#1f2933;line-height:1.6;">
  <p>Hi ${esc(toName)},</p>
  <p>Thank you for applying for the Junior AI Automation Engineer role. After reviewing
     your CV, we will not be moving forward with your application for this position.</p>
  <p>We will keep your details on file and encourage you to apply for future openings.</p>
  <p style="margin-top:24px;">Best regards,<br><strong>The Recruitment Team</strong></p>
  <hr style="border:none;border-top:1px solid #e3e8ef;margin:26px 0 10px;">
  <p style="font-size:11px;color:#9aa5b1;margin:0;">
    This message was generated automatically. If you believe this decision is wrong,
    simply reply to this email and a human will review it.
  </p>
</div>`;
return { toEmail, toName, subject, htmlBody };
